# arch-names.map: Arch package name -> Autark recipe name, read by scripts/arch-import.py.
# `-` means nothing to depend on: it is in the base system or installed outside autark-pkg.
gcc-libs gcc
gcc gcc
sh bash
glibc glibc
linux-api-headers -
git -
curl -
base-devel -
pkg-config pkgconf
openssl openssl
python3 python
ncurses ncurses
libgcc gcc
libstdc++ gcc
# Python build tooling: Autark has these under their PyPI names, and Arch's python-build, python-installer and
# python-pyproject-hooks need each other to build, so those three are hand-written recipes here.
python-flit-core flit-core
python-packaging packaging
python-setuptools setuptools
python-wheel wheel
python-jinja jinja2
python-markupsafe markupsafe
python-yaml pyyaml
# Rust is installed outside autark-pkg (rustc and cargo in the base system), so a Rust program needs nothing built for it.
rust -
cargo -
# Autark builds systemd whole; its libraries (libsystemd, libudev) are part of that recipe.
systemd-libs systemd
# The base system carries the CA bundle (/etc/pki/tls/certs/ca-bundle.crt); Arch's ca-certificates only generates one from p11-kit.
ca-certificates -
ca-certificates-mozilla -
ca-certificates-utils -
# pip is part of the base system (the recipes here build Python packages with pip3).
python-pip -
# The base builds LLVM and clang whole (llvm 22.x, with clang, lld and the libraries), so Arch's split and versioned packages are that recipe.
llvm-libs llvm
llvm22 llvm
llvm22-libs llvm
clang -
clang22 -
clang-libs -
# The base ships Lua 5.4 (lua), whose files lua54 would overwrite.
lua54 lua
# Arch splits libXScrnSaver as libxss; the base has it as libXScrnSaver.
libxss libXScrnSaver
# The base has PAM as linux-pam, with its /etc/pam.d files; Arch's pam and pambase are the same two things.
pam linux-pam
pambase -
# The base builds lld with the rest of LLVM.
lld llvm
lld22 llvm
# The base installs the util-linux libraries (libuuid, libblkid, libmount, ...) with util-linux.
util-linux-libs util-linux
# The base ships GLib 2.88 as glib (with gdbus-codegen, gi-compile-repository and the rest of what Arch splits out), and p11-kit with its library.
glib2 glib
glib2-devel glib
glib2-docs -
libp11-kit p11-kit
# libjpeg-turbo is the base libjpeg, and python-mako the base mako.
libjpeg-turbo libjpeg
python-mako mako
